//! Pure coordinate-level geometric predicates.
//!
//! These mirror the free-standing helpers of the C++ implementation one for
//! one, including the exact order of the floating point operations, so that
//! results are bit-identical.

/// Signed area of the triangle `(p, q, r)` (twice the area, sign encodes the
/// winding: negative means counter-clockwise in the convention used here).
#[inline]
pub fn area(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
}

/// `(0.0 < val) - (val < 0.0)`
#[inline]
pub fn sign(val: f64) -> i32 {
    (0.0 < val) as i32 - (val < 0.0) as i32
}

/// Whether `p` lies inside (or on the boundary of) the triangle `a, b, c`.
#[inline]
#[allow(clippy::too_many_arguments)]
pub fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

/// Bounding-box containment test used by the segment intersection routine:
/// for collinear points, whether `q` lies within the box spanned by `p`/`r`.
#[inline]
pub fn on_segment(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> bool {
    qx <= fmax(px, rx) && qx >= fmin(px, rx) && qy <= fmax(py, ry) && qy >= fmin(py, ry)
}

/// Z-order (Morton) curve value of a point, mapped into a 15 bit integer range.
#[inline]
pub fn z_order(x_: f64, y_: f64, min_x: f64, min_y: f64, inv_size: f64) -> i32 {
    // coords are transformed into non-negative 15-bit integer range
    let mut x = ((x_ - min_x) * inv_size) as i32;
    let mut y = ((y_ - min_y) * inv_size) as i32;

    x = (x | (x << 8)) & 0x00FF00FF;
    x = (x | (x << 4)) & 0x0F0F0F0F;
    x = (x | (x << 2)) & 0x3333_3333;
    x = (x | (x << 1)) & 0x5555_5555;

    y = (y | (y << 8)) & 0x00FF00FF;
    y = (y | (y << 4)) & 0x0F0F0F0F;
    y = (y | (y << 2)) & 0x3333_3333;
    y = (y | (y << 1)) & 0x5555_5555;

    x | (y << 1)
}

/// `std::min<double>` semantics: returns `b` only when `b < a`.
#[inline]
pub fn fmin(a: f64, b: f64) -> f64 {
    if b < a {
        b
    } else {
        a
    }
}

/// `std::max<double>` semantics: returns `b` only when `a < b`.
#[inline]
pub fn fmax(a: f64, b: f64) -> f64 {
    if a < b {
        b
    } else {
        a
    }
}

