//! Arena backed replacement for the pointer based node pool of the C++ code.
//!
//! The original allocates `Node` objects from an object pool and wires them up
//! with raw pointers. Here nodes live in a `Vec` and links are plain indices
//! into it; nodes are never moved or freed while a triangulation runs, so the
//! indices behave exactly like the original pointers.

/// Index of a node inside [`Arena`]. Always valid once the node was created.
pub type NodeRef = usize;

#[derive(Clone)]
pub struct Node {
    /// Index of the vertex in the flattened input coordinate sequence.
    pub i: u32,
    pub x: f64,
    pub y: f64,

    /// Previous and next vertex nodes in a polygon ring.
    pub prev: NodeRef,
    pub next: NodeRef,

    /// Z-order curve value.
    pub z: i32,

    /// Previous and next nodes in z-order.
    pub prev_z: Option<NodeRef>,
    pub next_z: Option<NodeRef>,

    /// Indicates whether this is a steiner point.
    pub steiner: bool,
}

impl Node {
    fn new(i: u32, x: f64, y: f64, self_ref: NodeRef) -> Node {
        Node {
            i,
            x,
            y,
            prev: self_ref,
            next: self_ref,
            z: 0,
            prev_z: None,
            next_z: None,
            steiner: false,
        }
    }
}

#[derive(Default)]
pub struct Arena {
    nodes: Vec<Node>,
}

impl Arena {
    pub fn new() -> Arena {
        Arena { nodes: Vec::new() }
    }

    /// Drop every node and reserve room for `capacity` new ones.
    pub fn reset(&mut self, capacity: usize) {
        self.nodes.clear();
        self.nodes.reserve(capacity);
    }

    pub fn clear(&mut self) {
        self.nodes.clear();
    }

    /// Allocate a node that initially links to itself.
    pub fn construct(&mut self, i: u32, x: f64, y: f64) -> NodeRef {
        let r = self.nodes.len();
        self.nodes.push(Node::new(i, x, y, r));
        r
    }
}

impl std::ops::Index<NodeRef> for Arena {
    type Output = Node;

    #[inline]
    fn index(&self, r: NodeRef) -> &Node {
        &self.nodes[r]
    }
}

impl std::ops::IndexMut<NodeRef> for Arena {
    #[inline]
    fn index_mut(&mut self, r: NodeRef) -> &mut Node {
        &mut self.nodes[r]
    }
}

