//! Ear-clipping triangulation, a faithful port of the `mapbox::earcut`
//! algorithm to safe Rust.
//!
//! The structure mirrors the original: a single `Earcut` state object owning a
//! node arena plus the emitted index buffer, and one method per step of the
//! algorithm. Traversal order, comparison operators and floating point
//! expressions are kept identical so the produced index list matches
//! bit-for-bit.

use super::geom::{area, fmax, fmin, on_segment, point_in_triangle, sign, z_order};
use super::node::{Arena, NodeRef};
use super::Point;

pub struct Earcut {
    arena: Arena,
    pub indices: Vec<u32>,
    vertices: usize,

    hashing: bool,
    min_x: f64,
    min_y: f64,
    max_x: f64,
    max_y: f64,
    inv_size: f64,
}

impl Earcut {
    pub fn new() -> Earcut {
        Earcut {
            arena: Arena::new(),
            indices: Vec::new(),
            vertices: 0,
            hashing: false,
            min_x: 0.0,
            min_y: 0.0,
            max_x: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    /// Triangulate a polygon given as an outer ring followed by hole rings.
    pub fn run<P: Point>(&mut self, points: &[Vec<P>]) {
        // reset
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            return;
        }

        let mut threshold: i32 = 80;
        let mut len: usize = 0;

        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            len += points[i].len();
            i += 1;
        }

        // estimate size of nodes and indices
        self.arena.reset(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = match self.linked_list(&points[0], true) {
            Some(n) => n,
            None => return,
        };
        if self.arena[outer_node].prev == self.arena[outer_node].next {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.arena[outer_node].next;
            self.min_x = self.arena[outer_node].x;
            self.max_x = self.min_x;
            self.min_y = self.arena[outer_node].y;
            self.max_y = self.min_y;
            loop {
                let x = self.arena[p].x;
                let y = self.arena[p].y;
                self.min_x = fmin(self.min_x, x);
                self.min_y = fmin(self.min_y, y);
                self.max_x = fmax(self.max_x, x);
                self.max_y = fmax(self.max_y, y);
                p = self.arena[p].next;
                if p == outer_node {
                    break;
                }
            }

            // minX, minY and size are later used to transform coords into
            // integers for z-order calculation
            self.inv_size = fmax(self.max_x - self.min_x, self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(Some(outer_node), 0);

        self.arena.clear();
    }

    /// Create a circular doubly linked list from polygon points in the
    /// specified winding order.
    fn linked_list<P: Point>(&mut self, points: &[P], clockwise: bool) -> Option<NodeRef> {
        let len = points.len();
        let mut sum = 0.0f64;
        let mut last: Option<NodeRef> = None;

        // calculate original winding order of a polygon ring
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p20 = points[j].x();
            let p10 = points[i].x();
            let p11 = points[i].y();
            let p21 = points[j].y();
            sum += (p20 - p10) * (p11 + p21);
            j = i;
        }

        // link points into circular doubly-linked list in the specified
        // winding order
        let base = self.vertices;
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = Some(self.insert_node(base + i, &points[i], last));
            }
        } else {
            for i in (0..len).rev() {
                last = Some(self.insert_node(base + i, &points[i], last));
            }
        }

        if let Some(l) = last {
            let n = self.arena[l].next;
            if self.equals(l, n) {
                self.remove_node(l);
                last = Some(self.arena[l].next);
            }
        }

        self.vertices += len;

        last
    }

    /// Eliminate colinear or duplicate points.
    fn filter_points(&mut self, start: NodeRef, end: Option<NodeRef>) -> NodeRef {
        let mut end = end.unwrap_or(start);

        let mut p = start;
        loop {
            let again;

            let p_next = self.arena[p].next;
            let p_prev = self.arena[p].prev;
            if !self.arena[p].steiner
                && (self.equals(p, p_next) || self.area3(p_prev, p, p_next) == 0.0)
            {
                self.remove_node(p);
                p = self.arena[p].prev;
                end = p;

                if p == self.arena[p].next {
                    break;
                }
                again = true;
            } else {
                p = p_next;
                again = false;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked
    /// list).
    fn earcut_linked(&mut self, ear: Option<NodeRef>, pass: i32) {
        let mut ear = match ear {
            Some(e) => e,
            None => return,
        };

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.arena[ear].prev != self.arena[ear].next {
            let prev = self.arena[ear].prev;
            let next = self.arena[ear].next;

            let cut = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if cut {
                // cut off the triangle
                let a = self.arena[prev].i;
                let b = self.arena[ear].i;
                let c = self.arena[next].i;
                self.indices.push(a);
                self.indices.push(b);
                self.indices.push(c);

                self.remove_node(ear);

                // skipping the next vertice leads to less sliver triangles
                ear = self.arena[next].next;
                stop = self.arena[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find
            // any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let f = self.filter_points(ear, None);
                    self.earcut_linked(Some(f), 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small
                    // self-intersections locally
                    let f = self.filter_points(ear, None);
                    let cured = self.cure_local_intersections(f);
                    self.earcut_linked(Some(cured), 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon
                    // into two
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: NodeRef) -> bool {
        let a = self.arena[ear].prev;
        let b = ear;
        let c = self.arena[ear].next;

        if self.area3(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.arena[a].x, self.arena[a].y);
        let (bx, by) = (self.arena[b].x, self.arena[b].y);
        let (cx, cy) = (self.arena[c].x, self.arena[c].y);

        // now make sure we don't have other points inside the potential ear
        let mut p = self.arena[c].next;

        while p != a {
            let (px, py) = (self.arena[p].x, self.arena[p].y);
            let p_prev = self.arena[p].prev;
            let p_next = self.arena[p].next;
            if point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
                && self.area3(p_prev, p, p_next) >= 0.0
            {
                return false;
            }
            p = p_next;
        }

        true
    }

    /// Same as [`Earcut::is_ear`] but restricted to the z-order neighbourhood
    /// of the triangle's bounding box.
    fn is_ear_hashed(&self, ear: NodeRef) -> bool {
        let a = self.arena[ear].prev;
        let b = ear;
        let c = self.arena[ear].next;

        if self.area3(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.arena[a].x, self.arena[a].y);
        let (bx, by) = (self.arena[b].x, self.arena[b].y);
        let (cx, cy) = (self.arena[c].x, self.arena[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = fmin(ax, fmin(bx, cx));
        let min_ty = fmin(ay, fmin(by, cy));
        let max_tx = fmax(ax, fmax(bx, cx));
        let max_ty = fmax(ay, fmax(by, cy));

        // z-order range for the current triangle bbox
        let min_z = z_order(min_tx, min_ty, self.min_x, self.min_y, self.inv_size);
        let max_z = z_order(max_tx, max_ty, self.min_x, self.min_y, self.inv_size);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.arena[ear].next_z;
        let mut n = self.arena[ear].prev_z;

        while let (Some(pp), Some(nn)) = (p, n) {
            if self.arena[pp].z > max_z || self.arena[nn].z < min_z {
                break;
            }

            if pp != a
                && pp != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.arena[pp].x, self.arena[pp].y)
                && self.area3(self.arena[pp].prev, pp, self.arena[pp].next) >= 0.0
            {
                return false;
            }
            p = self.arena[pp].next_z;

            if nn != a
                && nn != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.arena[nn].x, self.arena[nn].y)
                && self.area3(self.arena[nn].prev, nn, self.arena[nn].next) >= 0.0
            {
                return false;
            }
            n = self.arena[nn].prev_z;
        }

        // look for remaining points in decreasing z-order
        while let Some(nn) = n {
            if self.arena[nn].z < min_z {
                break;
            }
            if nn != a
                && nn != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.arena[nn].x, self.arena[nn].y)
                && self.area3(self.arena[nn].prev, nn, self.arena[nn].next) >= 0.0
            {
                return false;
            }
            n = self.arena[nn].prev_z;
        }

        // look for remaining points in increasing z-order
        while let Some(pp) = p {
            if self.arena[pp].z > max_z {
                break;
            }
            if pp != a
                && pp != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.arena[pp].x, self.arena[pp].y)
                && self.area3(self.arena[pp].prev, pp, self.arena[pp].next) >= 0.0
            {
                return false;
            }
            p = self.arena[pp].next_z;
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    fn cure_local_intersections(&mut self, start: NodeRef) -> NodeRef {
        let mut start = start;
        let mut p = start;
        loop {
            let a = self.arena[p].prev;
            let p_next = self.arena[p].next;
            let b = self.arena[p_next].next;

            // a self-intersection where edge (v[i-1],v[i]) intersects
            // (v[i+1],v[i+2])
            if !self.equals(a, b)
                && self.intersects(a, p, p_next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                let ia = self.arena[a].i;
                let ip = self.arena[p].i;
                let ib = self.arena[b].i;
                self.indices.push(ia);
                self.indices.push(ip);
                self.indices.push(ib);

                // remove two nodes involved
                self.remove_node(p);
                let after = self.arena[p].next;
                self.remove_node(after);

                p = b;
                start = b;
            }
            p = self.arena[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, None)
    }

    /// Try splitting polygon into two and triangulate them independently.
    fn split_earcut(&mut self, start: NodeRef) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let a_next = self.arena[a].next;
            let mut b = self.arena[a_next].next;
            while b != self.arena[a].prev {
                if self.arena[a].i != self.arena[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let an = self.arena[a].next;
                    let a2 = self.filter_points(a, Some(an));
                    let cn = self.arena[c].next;
                    let c2 = self.filter_points(c, Some(cn));

                    // run earcut on each half
                    self.earcut_linked(Some(a2), 0);
                    self.earcut_linked(Some(c2), 0);
                    return;
                }
                b = self.arena[b].next;
            }
            a = self.arena[a].next;
            if a == start {
                break;
            }
        }
    }

    /// Link every hole into the outer loop, producing a single-ring polygon.
    fn eliminate_holes<P: Point>(
        &mut self,
        points: &[Vec<P>],
        mut outer_node: NodeRef,
    ) -> NodeRef {
        let len = points.len();

        let mut queue: Vec<NodeRef> = Vec::new();
        for i in 1..len {
            if let Some(list) = self.linked_list(&points[i], false) {
                if list == self.arena[list].next {
                    self.arena[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }

        {
            let arena = &self.arena;
            queue.sort_by(|&a, &b| {
                arena[a]
                    .x
                    .partial_cmp(&arena[b].x)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });
        }

        // process holes from left to right
        for i in 0..queue.len() {
            outer_node = self.eliminate_hole(queue[i], outer_node);
        }

        outer_node
    }

    /// Find a bridge between vertices that connects a hole with an outer ring
    /// and link it.
    fn eliminate_hole(&mut self, hole: NodeRef, outer_node: NodeRef) -> NodeRef {
        let bridge = match self.find_hole_bridge(hole, outer_node) {
            Some(b) => b,
            None => return outer_node,
        };

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let brn = self.arena[bridge_reverse].next;
        self.filter_points(bridge_reverse, Some(brn));

        // Check if input node was removed by the filtering
        let bn = self.arena[bridge].next;
        self.filter_points(bridge, Some(bn))
    }

    /// David Eberly's algorithm for finding a bridge between hole and outer
    /// polygon.
    fn find_hole_bridge(&self, hole: NodeRef, outer_node: NodeRef) -> Option<NodeRef> {
        let mut p = outer_node;
        let hx = self.arena[hole].x;
        let hy = self.arena[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m: Option<NodeRef> = None;

        // find a segment intersected by a ray from the hole's leftmost vertex
        // to the left; segment's endpoint with lesser x will be potential
        // connection vertex
        loop {
            let p_next = self.arena[p].next;
            let (px, py) = (self.arena[p].x, self.arena[p].y);
            let (nx, ny) = (self.arena[p_next].x, self.arena[p_next].y);
            if hy <= py && hy >= ny && ny != py {
                let x = px + (hy - py) * (nx - px) / (ny - py);
                if x <= hx && x > qx {
                    qx = x;
                    m = Some(if px < nx { p } else { p_next });
                    if x == hx {
                        // hole touches outer segment; pick leftmost endpoint
                        return m;
                    }
                }
            }
            p = p_next;
            if p == outer_node {
                break;
            }
        }

        let mut m = m?;

        // look for points inside the triangle of hole vertex, segment
        // intersection and endpoint; if there are no points found, we have a
        // valid connection; otherwise choose the vertex of the minimum angle
        // with the ray as connection vertex

        let stop = m;
        let mut tan_min = f64::INFINITY;

        let mut p = m;
        let mx = self.arena[m].x;
        let my = self.arena[m].y;

        loop {
            let (px, py) = (self.arena[p].x, self.arena[p].y);
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px); // tangential

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.arena[m].x || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.arena[p].next;
            if p == stop {
                break;
            }
        }

        Some(m)
    }

    /// Whether sector in vertex m contains sector in vertex p in the same
    /// coordinates.
    fn sector_contains_sector(&self, m: NodeRef, p: NodeRef) -> bool {
        let m_prev = self.arena[m].prev;
        let m_next = self.arena[m].next;
        let p_prev = self.arena[p].prev;
        let p_next = self.arena[p].next;
        self.area3(m_prev, m, p_prev) < 0.0 && self.area3(p_next, m, m_next) < 0.0
    }

    /// Interlink polygon nodes in z-order.
    fn index_curve(&mut self, start: NodeRef) {
        let mut p = start;

        loop {
            if self.arena[p].z == 0 {
                let (x, y) = (self.arena[p].x, self.arena[p].y);
                self.arena[p].z = z_order(x, y, self.min_x, self.min_y, self.inv_size);
            }
            let prev = self.arena[p].prev;
            let next = self.arena[p].next;
            self.arena[p].prev_z = Some(prev);
            self.arena[p].next_z = Some(next);
            p = next;
            if p == start {
                break;
            }
        }

        let prev_z = self.arena[p].prev_z.expect("z-list is circular here");
        self.arena[prev_z].next_z = None;
        self.arena[p].prev_z = None;

        self.sort_linked(p);
    }

    /// Simon Tatham's linked list merge sort algorithm, sorting by z-order.
    fn sort_linked(&mut self, list_head: NodeRef) -> NodeRef {
        let mut list: Option<NodeRef> = Some(list_head);
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = None;
            let mut tail: Option<NodeRef> = None;
            let mut num_merges = 0;

            while let Some(p_head) = p {
                num_merges += 1;
                let mut q = Some(p_head);
                let mut p_size: i32 = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.arena[q.unwrap()].next_z;
                    if q.is_none() {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q.is_some()) {
                    let e;

                    if p_size == 0 {
                        e = q.unwrap();
                        q = self.arena[e].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q.is_none() {
                        e = p.unwrap();
                        p = self.arena[e].next_z;
                        p_size -= 1;
                    } else if self.arena[p.unwrap()].z <= self.arena[q.unwrap()].z {
                        e = p.unwrap();
                        p = self.arena[e].next_z;
                        p_size -= 1;
                    } else {
                        e = q.unwrap();
                        q = self.arena[e].next_z;
                        q_size -= 1;
                    }

                    match tail {
                        Some(t) => self.arena[t].next_z = Some(e),
                        None => list = Some(e),
                    }

                    self.arena[e].prev_z = tail;
                    tail = Some(e);
                }

                p = q;
            }

            if let Some(t) = tail {
                self.arena[t].next_z = None;
            }

            if num_merges <= 1 {
                return list.unwrap();
            }

            in_size *= 2;
        }
    }

    /// Find the leftmost node of a polygon ring.
    fn get_leftmost(&self, start: NodeRef) -> NodeRef {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.arena[p].x < self.arena[leftmost].x
                || (self.arena[p].x == self.arena[leftmost].x
                    && self.arena[p].y < self.arena[leftmost].y)
            {
                leftmost = p;
            }
            p = self.arena[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    /// Check if a diagonal between two polygon nodes is valid (lies in polygon
    /// interior).
    fn is_valid_diagonal(&self, a: NodeRef, b: NodeRef) -> bool {
        let a_next = self.arena[a].next;
        let a_prev = self.arena[a].prev;
        let b_next = self.arena[b].next;
        let b_prev = self.arena[b].prev;
        let bi = self.arena[b].i;

        self.arena[a_next].i != bi
            && self.arena[a_prev].i != bi
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b) // locally visible
                // does not create opposite-facing sectors
                && (self.area3(a_prev, a, b_prev) != 0.0 || self.area3(a, b_prev, b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area3(a_prev, a, a_next) > 0.0
                    && self.area3(b_prev, b, b_next) > 0.0))
    }

    /// Signed area of a triangle addressed by node references.
    #[inline]
    fn area3(&self, p: NodeRef, q: NodeRef, r: NodeRef) -> f64 {
        area(
            self.arena[p].x,
            self.arena[p].y,
            self.arena[q].x,
            self.arena[q].y,
            self.arena[r].x,
            self.arena[r].y,
        )
    }

    /// Check if two points are equal.
    #[inline]
    fn equals(&self, p1: NodeRef, p2: NodeRef) -> bool {
        self.arena[p1].x == self.arena[p2].x && self.arena[p1].y == self.arena[p2].y
    }

    /// Check if two segments intersect.
    fn intersects(&self, p1: NodeRef, q1: NodeRef, p2: NodeRef, q2: NodeRef) -> bool {
        let o1 = sign(self.area3(p1, q1, p2));
        let o2 = sign(self.area3(p1, q1, q2));
        let o3 = sign(self.area3(p2, q2, p1));
        let o4 = sign(self.area3(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        // p1, q1 and p2 are collinear and p2 lies on p1q1
        if o1 == 0 && self.on_seg(p1, p2, q1) {
            return true;
        }
        // p1, q1 and q2 are collinear and q2 lies on p1q1
        if o2 == 0 && self.on_seg(p1, q2, q1) {
            return true;
        }
        // p2, q2 and p1 are collinear and p1 lies on p2q2
        if o3 == 0 && self.on_seg(p2, p1, q2) {
            return true;
        }
        // p2, q2 and q1 are collinear and q1 lies on p2q2
        if o4 == 0 && self.on_seg(p2, q1, q2) {
            return true;
        }

        false
    }

    #[inline]
    fn on_seg(&self, p: NodeRef, q: NodeRef, r: NodeRef) -> bool {
        on_segment(
            self.arena[p].x,
            self.arena[p].y,
            self.arena[q].x,
            self.arena[q].y,
            self.arena[r].x,
            self.arena[r].y,
        )
    }

    /// Check if a polygon diagonal intersects any polygon segments.
    fn intersects_polygon(&self, a: NodeRef, b: NodeRef) -> bool {
        let ai = self.arena[a].i;
        let bi = self.arena[b].i;
        let mut p = a;
        loop {
            let p_next = self.arena[p].next;
            let pi = self.arena[p].i;
            let ni = self.arena[p_next].i;
            if pi != ai && ni != ai && pi != bi && ni != bi && self.intersects(p, p_next, a, b) {
                return true;
            }
            p = p_next;
            if p == a {
                break;
            }
        }
        false
    }

    /// Check if a polygon diagonal is locally inside the polygon.
    fn locally_inside(&self, a: NodeRef, b: NodeRef) -> bool {
        let a_prev = self.arena[a].prev;
        let a_next = self.arena[a].next;
        if self.area3(a_prev, a, a_next) < 0.0 {
            self.area3(a, b, a_next) >= 0.0 && self.area3(a, a_prev, b) >= 0.0
        } else {
            self.area3(a, b, a_prev) < 0.0 || self.area3(a, a_next, b) < 0.0
        }
    }

    /// Check if the middle vertex of a polygon diagonal is inside the polygon.
    fn middle_inside(&self, a: NodeRef, b: NodeRef) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.arena[a].x + self.arena[b].x) / 2.0;
        let py = (self.arena[a].y + self.arena[b].y) / 2.0;
        loop {
            let p_next = self.arena[p].next;
            let (cx, cy) = (self.arena[p].x, self.arena[p].y);
            let (nx, ny) = (self.arena[p_next].x, self.arena[p_next].y);
            if ((cy > py) != (ny > py))
                && ny != cy
                && (px < (nx - cx) * (py - cy) / (ny - cy) + cx)
            {
                inside = !inside;
            }
            p = p_next;
            if p == a {
                break;
            }
        }

        inside
    }

    /// Link two polygon vertices with a bridge; if the vertices belong to the
    /// same ring, it splits the polygon into two. If one belongs to the outer
    /// ring and another to a hole, it merges it into a single ring.
    fn split_polygon(&mut self, a: NodeRef, b: NodeRef) -> NodeRef {
        let (ai, ax, ay) = (self.arena[a].i, self.arena[a].x, self.arena[a].y);
        let (bi, bx, by) = (self.arena[b].i, self.arena[b].x, self.arena[b].y);
        let a2 = self.arena.construct(ai, ax, ay);
        let b2 = self.arena.construct(bi, bx, by);
        let an = self.arena[a].next;
        let bp = self.arena[b].prev;

        self.arena[a].next = b;
        self.arena[b].prev = a;

        self.arena[a2].next = an;
        self.arena[an].prev = a2;

        self.arena[b2].next = a2;
        self.arena[a2].prev = b2;

        self.arena[bp].next = b2;
        self.arena[b2].prev = bp;

        b2
    }

    /// Create a node and optionally link it with the previous one (in a
    /// circular doubly linked list).
    fn insert_node<P: Point>(&mut self, i: usize, pt: &P, last: Option<NodeRef>) -> NodeRef {
        let p = self.arena.construct(i as u32, pt.x(), pt.y());

        match last {
            None => {
                // `construct` already links the node to itself
            }
            Some(l) => {
                let ln = self.arena[l].next;
                self.arena[p].next = ln;
                self.arena[p].prev = l;
                self.arena[ln].prev = p;
                self.arena[l].next = p;
            }
        }
        p
    }

    fn remove_node(&mut self, p: NodeRef) {
        let next = self.arena[p].next;
        let prev = self.arena[p].prev;
        self.arena[next].prev = prev;
        self.arena[prev].next = next;

        let prev_z = self.arena[p].prev_z;
        let next_z = self.arena[p].next_z;
        if let Some(pz) = prev_z {
            self.arena[pz].next_z = next_z;
        }
        if let Some(nz) = next_z {
            self.arena[nz].prev_z = prev_z;
        }
    }
}

impl Default for Earcut {
    fn default() -> Earcut {
        Earcut::new()
    }
}

input.content:
//! A dependency-free Rust port of `mapbox::earcut` — a fast polygon
//! triangulation library that handles holes.
//!
//! ```ignore
//! let polygon = vec![vec![[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]]];
//! let indices = earcut::earcut(&polygon);
//! ```

pub mod algorithm;
pub mod geom;
pub mod node;

pub use algorithm::Earcut;

/// Anything that can act as a 2D vertex of an input ring.
///
/// Plays the role of `mapbox::util::nth<0/1, Point>` in the C++ original.
pub trait Point {
    fn x(&self) -> f64;
    fn y(&self) -> f64;
}

impl Point for [f64; 2] {
    #[inline]
    fn x(&self) -> f64 {
        self[0]
    }
    #[inline]
    fn y(&self) -> f64 {
        self[1]
    }
}

impl Point for (f64, f64) {
    #[inline]
    fn x(&self) -> f64 {
        self.0
    }
    #[inline]
    fn y(&self) -> f64 {
        self.1
    }
}

/// Triangulate `polygon`, given as an outer ring followed by any number of
/// hole rings, and return a flat list of triangle vertex indices.
pub fn earcut<P: Point>(polygon: &[Vec<P>]) -> Vec<u32> {
    let mut earcut = Earcut::new();
    earcut.run(polygon);
    earcut.indices
}

