mod earcut;

use std::io::Write;

/// Reimplementation of C's `atoi`: skip leading whitespace, accept an optional
/// sign, then consume decimal digits until the first non-digit.
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() && (bytes[i] as char).is_ascii_whitespace() {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value.saturating_mul(10).saturating_add((bytes[i] - b'0') as i64);
        i += 1;
    }

    if negative {
        value = -value;
    }
    value.clamp(i32::MIN as i64, i32::MAX as i64) as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut n: i32 = 4;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();

    for i in 0..n {
        let mut ring: Vec<[f64; 2]> = Vec::new();
        let offset = (i * 2) as f64;
        let side = n as f64;
        ring.push([offset, offset]);
        ring.push([offset + side, offset]);
        ring.push([offset + side, offset + side]);
        ring.push([offset, offset + side]);
        polygon.push(ring);
    }

    let indices = earcut::earcut(&polygon);

    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for idx in indices {
        write!(out, "{} ", idx).unwrap();
    }
    out.flush().unwrap();
}

